"El Pesebre": "The Beehive",
"El Seestar debe estar en modo estación (unido a tu wifi). Actívalo una vez desde la app oficial.": "The Seestar must be in station mode (joined to your Wi-Fi). Enable it once from the official app.",
"El Seestar tiene un %@ %% y el plan dura unas %@ h; con tu consumo medio (%@ %%/h) terminaría sin batería. Conecta el cargador o acorta el plan.": "The Seestar is at %@ %% and the plan lasts about %@ h; at your average use (%@ %%/h) it would run out of battery. Plug in the charger or shorten the plan.",
"El Seestar ve la Luna entera de una vez (su campo mide 44′ × 77′ y la Luna unos 31′), así que no hace falta apuntar a cada cráter: usa el modo Luna y amplía la imagen.": "The Seestar sees the whole Moon at once (its field is 44′ × 77′ and the Moon about 31′), so there is no need to point at each crater: use Moon mode and zoom into the image.",
