"El modo Luna sigue la Luna y muestra la imagen en «Vista en directo». Para un mosaico o un vídeo, graba con la app y apílalo en «Apilador planetario».": "Moon mode tracks the Moon and shows the image in “Live view”. For a mosaic or a video, record with the app and stack it in “Planetary stacker”.",
