"Arrastra aquí un vídeo de un planeta o de la Luna": "Glissez ici une vidéo d'une planète ou de la Lune",
"Arrastra una barra para retrasar su inicio; arrastra su borde derecho para cambiar la duración. Detrás de cada barra, en verde, cuándo se ve el objeto (altura mínima y tu horizonte).": "Faites glisser une barre pour retarder son début ; faites glisser son bord droit pour changer la durée. Derrière chaque barre, en vert, quand l’objet est visible (hauteur minimale et votre horizon).",
"Arriba": "Haut",
"Astrolabio": "Astrolabio",
"Astrolabio anota cada sesión de apilado mientras está conectado al Seestar: el objeto, la hora, los fotogramas y el tiempo de integración. Cuando apiles algo, aparecerá aquí. También puedes traer las sesiones anteriores con «Importar del Seestar».": "Astrolabio note chaque session d'empilement pendant qu'il est connecté au Seestar : l'objet, l'heure, les images et le temps d'intégration. Quand vous empilerez quelque chose, cela apparaîtra ici. Vous pouvez aussi récupérer les sessions précédentes avec « Importer du Seestar ».",
"Astrolabio es independiente y no está afiliado a ZWO.": "Astrolabio est indépendant et n'est pas affilié à ZWO.",
"Astrolabio mide el tamaño de las estrellas en cada apilado. Si crecen, suele ser el enfoque (cambio de temperatura) o rocío en la lente.": "Astrolabio mesure la taille des étoiles à chaque empilement. Si elles grossissent, c’est en général la mise au point (changement de température) ou de la rosée sur l’objectif.",
"Astrolabio puede avisarte en el móvil de lo que pasa durante la noche, aunque estés lejos del Mac. **No hace falta número de teléfono ni crear una cuenta**: se usa ntfy, una app gratuita para iPhone y Android.": "Astrolabio peut vous prévenir sur votre téléphone de ce qui se passe pendant la nuit, même loin du Mac. **Pas besoin de numéro de téléphone ni de compte** : il utilise ntfy, une app gratuite pour iPhone et Android.",
