"Dibuja con el ratón la altura de lo que tapa el cielo desde tu sitio: árboles, tejados, montes. Los objetos que queden detrás no se sugieren y la sesión automática los espera o los salta.": "Dessinez à la souris la hauteur de ce qui cache le ciel depuis votre lieu : arbres, toits, collines. Les objets derrière ne sont pas suggérés et la session automatique les attend ou les ignore.",
