"El Seestar debe estar en modo estación (unido a tu wifi). Actívalo una vez desde la app oficial.": "Le Seestar doit être en mode station (connecté à votre Wi-Fi). Activez-le une fois depuis l'app officielle.",
"El Seestar tiene un %@ %% y el plan dura unas %@ h; con tu consumo medio (%@ %%/h) terminaría sin batería. Conecta el cargador o acorta el plan.": "Le Seestar est à %@ %% et le plan dure environ %@ h ; avec votre consommation moyenne (%@ %%/h), la batterie serait vide. Branchez le chargeur ou raccourcissez le plan.",
"El Seestar ve la Luna entera de una vez (su campo mide 44′ × 77′ y la Luna unos 31′), así que no hace falta apuntar a cada cráter: usa el modo Luna y amplía la imagen.": "Le Seestar voit la Lune entière d’un coup (champ de 44′ × 77′, Lune d’environ 31′) : inutile de viser chaque cratère, utilisez le mode Lune et agrandissez l’image.",
