"El firmware reciente del Seestar exige que el cliente firme un reto con una clave privada. Indica aquí el archivo .pem que uses con seestar_alp (opción interop_pem).": "Le firmware récent du Seestar exige que le client signe un défi avec une clé privée. Indiquez ici le fichier .pem utilisé avec seestar_alp (option interop_pem).",
"El modo Luna sigue la Luna y muestra la imagen en «Vista en directo». Para un mosaico o un vídeo, graba con la app y apílalo en «Apilador planetario».": "Le mode Lune suit la Lune et affiche l'image dans « Vue en direct ». Pour une mosaïque ou une vidéo, enregistrez avec l'app et empilez-la dans « Empileur planétaire ».",
