"La Luna y %@": "La Lune et %@",
"La clave PEM la pueden leer otros usuarios de este Mac. Protégela con: chmod 600 \"%@\"": "D’autres utilisateurs de ce Mac peuvent lire la clé PEM. Protégez-la avec : chmod 600 \"%@\"",
