"Arrastra aquí un vídeo de un planeta o de la Luna": "Ziehe ein Video eines Planeten oder des Mondes hierher",
"Arrastra una barra para retrasar su inicio; arrastra su borde derecho para cambiar la duración. Detrás de cada barra, en verde, cuándo se ve el objeto (altura mínima y tu horizonte).": "Ziehe einen Balken, um den Beginn zu verschieben; ziehe seinen rechten Rand, um die Dauer zu ändern. Hinter jedem Balken in Grün, wann das Objekt sichtbar ist (Mindesthöhe und dein Horizont).",
"Arriba": "Oben",
"Astrolabio": "Astrolabio",
"Astrolabio anota cada sesión de apilado mientras está conectado al Seestar: el objeto, la hora, los fotogramas y el tiempo de integración. Cuando apiles algo, aparecerá aquí. También puedes traer las sesiones anteriores con «Importar del Seestar».": "Astrolabio protokolliert jede Stacking-Sitzung, solange es mit dem Seestar verbunden ist: Objekt, Uhrzeit, Bilder und Integrationszeit. Sobald du etwas stackst, erscheint es hier. Frühere Sitzungen holst du mit „Vom Seestar importieren“.",
"Astrolabio es independiente y no está afiliado a ZWO.": "Astrolabio ist unabhängig und nicht mit ZWO verbunden.",
"Astrolabio mide el tamaño de las estrellas en cada apilado. Si crecen, suele ser el enfoque (cambio de temperatura) o rocío en la lente.": "Astrolabio misst in jedem Stack die Sterngröße. Werden die Sterne größer, liegt es meist am Fokus (Temperaturänderung) oder an Tau auf der Linse.",
"Astrolabio puede avisarte en el móvil de lo que pasa durante la noche, aunque estés lejos del Mac. **No hace falta número de teléfono ni crear una cuenta**: se usa ntfy, una app gratuita para iPhone y Android.": "Astrolabio kann dich auf dem Handy über die Nacht informieren, auch wenn du nicht am Mac bist. **Keine Telefonnummer und kein Konto nötig**: Es nutzt ntfy, eine kostenlose App für iPhone und Android.",
