"Cómo funciona: eliges un «tema», que es como el nombre de un canal privado. Astrolabio publica los avisos en ese tema y la app ntfy del móvil, suscrita a él, te los muestra como notificaciones.": "So funktioniert es: Du wählst ein „Thema“, quasi den Namen eines privaten Kanals. Astrolabio veröffentlicht die Hinweise in diesem Thema, und die ntfy-App auf dem Handy, die es abonniert hat, zeigt sie als Mitteilungen an.",
