"El Pesebre": "Krippe",
"El Seestar debe estar en modo estación (unido a tu wifi). Actívalo una vez desde la app oficial.": "Das Seestar muss im Stationsmodus sein (mit deinem WLAN verbunden). Aktiviere ihn einmal in der offiziellen App.",
"El Seestar tiene un %@ %% y el plan dura unas %@ h; con tu consumo medio (%@ %%/h) terminaría sin batería. Conecta el cargador o acorta el plan.": "Der Seestar hat %@ %% und der Plan dauert etwa %@ h; bei deinem mittleren Verbrauch (%@ %%/h) wäre der Akku leer. Schließe das Ladegerät an oder kürze den Plan.",
"El Seestar ve la Luna entera de una vez (su campo mide 44′ × 77′ y la Luna unos 31′), así que no hace falta apuntar a cada cráter: usa el modo Luna y amplía la imagen.": "Das Seestar sieht den ganzen Mond auf einmal (Bildfeld 44′ × 77′, Mond etwa 31′), daher muss man nicht jeden Krater anfahren: Mondmodus nutzen und ins Bild zoomen.",
"El archivo PEM no es válido.": "Die PEM-Datei ist ungültig.",
"El archivo es demasiado grande para ser una copia de Astrolabio.": "Die Datei ist zu groß für eine Astrolabio-Sicherung.",
"El archivo no contiene vídeo.": "Die Datei enthält kein Video.",
"El enfoque automático falló.": "Autofokus fehlgeschlagen.",
"El enfoque falló; se sigue con el enfoque actual.": "Fokussieren fehlgeschlagen; es geht mit dem aktuellen Fokus weiter.",
"El firmware reciente del Seestar exige que el cliente firme un reto con una clave privada. Indica aquí el archivo .pem que uses con seestar_alp (opción interop_pem).": "Aktuelle Seestar-Firmware verlangt, dass der Client eine Challenge mit einem privaten Schlüssel signiert. Gib hier die .pem-Datei an, die du mit seestar_alp nutzt (Option interop_pem).",
"El modo Luna sigue la Luna y muestra la imagen en «Vista en directo». Para un mosaico o un vídeo, graba con la app y apílalo en «Apilador planetario».": "Der Mondmodus verfolgt den Mond und zeigt das Bild in der „Live-Ansicht“. Für ein Mosaik oder Video nimm mit der App auf und staple es im „Planeten-Stacker“.",
