"Arrastra aquí un vídeo de un planeta o de la Luna": "把行星或月亮的视频拖到这里",
"Arrastra una barra para retrasar su inicio; arrastra su borde derecho para cambiar la duración. Detrás de cada barra, en verde, cuándo se ve el objeto (altura mínima y tu horizonte).": "拖动条块可推迟开始；拖动右边缘可改变时长。每个条块后面的绿色表示天体可见的时段（最低高度和你的地平线）。",
"Arriba": "上",
"Astrolabio": "Astrolabio",
"Astrolabio anota cada sesión de apilado mientras está conectado al Seestar: el objeto, la hora, los fotogramas y el tiempo de integración. Cuando apiles algo, aparecerá aquí. También puedes traer las sesiones anteriores con «Importar del Seestar».": "连接 Seestar 时，Astrolabio 会记录每次叠加：天体、时间、帧数和累计曝光时间。叠加后会显示在这里。也可以用“从 Seestar 导入”找回以前的记录。",
"Astrolabio es independiente y no está afiliado a ZWO.": "Astrolabio 是独立软件，与 ZWO 无关。",
"Astrolabio mide el tamaño de las estrellas en cada apilado. Si crecen, suele ser el enfoque (cambio de temperatura) o rocío en la lente.": "Astrolabio 会在每次叠加时测量星点大小。星点变大通常是对焦（温度变化）或镜头结露所致。",
"Astrolabio puede avisarte en el móvil de lo que pasa durante la noche, aunque estés lejos del Mac. **No hace falta número de teléfono ni crear una cuenta**: se usa ntfy, una app gratuita para iPhone y Android.": "Astrolabio 可以在手机上提醒你夜间发生的事情，即使你不在 Mac 旁边。**无需手机号，也无需注册账号**：它使用 ntfy，一款免费的 iPhone 和 Android 应用。",
"Autenticación correcta.": "认证成功。",
