"Copia las carpetas elegidas con todos sus archivos, comprueba cada uno y continúa donde lo dejó. No borra nada del telescopio.": "复制所选文件夹及其全部文件，逐个校验，并可从中断处继续。不会删除望远镜上的任何内容。",
