"Cómo funciona: eliges un «tema», que es como el nombre de un canal privado. Astrolabio publica los avisos en ese tema y la app ntfy del móvil, suscrita a él, te los muestra como notificaciones.": "原理：你选择一个“主题”，相当于私人频道的名称。Astrolabio 把提醒发布到这个主题，手机上订阅了它的 ntfy 应用就会以通知形式显示。",
