"Dibuja con el ratón la altura de lo que tapa el cielo desde tu sitio: árboles, tejados, montes. Los objetos que queden detrás no se sugieren y la sesión automática los espera o los salta.": "用鼠标画出从你的位置遮挡天空的物体高度：树木、屋顶、山丘。被遮挡的天体不会被推荐，自动观测会等待或跳过它们。",
