"El FITS conserva los datos lineales para procesarlos en Siril o GraXpert.": "FITS 文件保留线性数据，可在 Siril 或 GraXpert 中处理。",
"El GoTo a %@ no terminó bien (¿nubes o poca altura?).": "指向 %@ 未成功完成（有云或高度太低？）。",
