"El Pesebre": "蜂巢星团",
"El Seestar debe estar en modo estación (unido a tu wifi). Actívalo una vez desde la app oficial.": "Seestar 需处于站点模式（连接你的 Wi-Fi）。请在官方应用中开启一次。",
"El Seestar tiene un %@ %% y el plan dura unas %@ h; con tu consumo medio (%@ %%/h) terminaría sin batería. Conecta el cargador o acorta el plan.": "Seestar 电量为 %1$@%%，计划约 %2$@ 小时；按你的平均耗电（%3$@%%/小时）电量将耗尽。请连接充电器或缩短计划。",
"El Seestar ve la Luna entera de una vez (su campo mide 44′ × 77′ y la Luna unos 31′), así que no hace falta apuntar a cada cráter: usa el modo Luna y amplía la imagen.": "Seestar 一次就能看到整个月亮（视场 44′ × 77′，月亮约 31′），无需逐个指向环形山：使用月亮模式并放大图像即可。",
"El archivo PEM no es válido.": "PEM 文件无效。",
"El archivo es demasiado grande para ser una copia de Astrolabio.": "文件太大，不是 Astrolabio 备份。",
"El archivo no contiene vídeo.": "该文件不包含视频。",
"El enfoque automático falló.": "自动对焦失败。",
"El enfoque falló; se sigue con el enfoque actual.": "对焦失败；继续使用当前对焦。",
"El firmware reciente del Seestar exige que el cliente firme un reto con una clave privada. Indica aquí el archivo .pem que uses con seestar_alp (opción interop_pem).": "新版 Seestar 固件要求客户端用私钥对验证码签名。请在此选择你在 seestar_alp 中使用的 .pem 文件（interop_pem 选项）。",
"El modo Luna sigue la Luna y muestra la imagen en «Vista en directo». Para un mosaico o un vídeo, graba con la app y apílalo en «Apilador planetario».": "月球模式会跟踪月亮并在“实时画面”中显示。若要拼接或拍视频，用官方应用录制后在“行星叠加器”中叠加。",
"El plan de la noche ha terminado.": "今晚的计划已完成。",
"El plan de la sesión automática ha terminado.": "自动拍摄计划已完成。",
"El plan está vacío. Añade objetos desde «Planificar la noche» o «Mosaicos».": "计划为空。请从“规划今晚”或“拼接”中添加天体。",
"El plan termina a las %@, %@ min después del amanecer.": "计划于 %1$@ 结束，比黎明晚 %2$@ 分钟。",
"El plan termina a las %@; sobran %@ min de noche.": "计划于 %1$@ 结束；还剩 %2$@ 分钟夜晚。",
