"Aquí aparecen las fotos guardadas desde la vista en directo, el apilador planetario y las descargas del álbum.": "Здесь появляются снимки, сохранённые из живого просмотра, планетного стекера и загрузок из альбома.",
"Archivo": "Архив",
"Archivos": "Файлы",
"Arrastra aquí un vídeo de un planeta o de la Luna": "Перетащите сюда видео планеты или Луны",
"Arrastra una barra para retrasar su inicio; arrastra su borde derecho para cambiar la duración. Detrás de cada barra, en verde, cuándo se ve el objeto (altura mínima y tu horizonte).": "Перетащите полосу, чтобы отложить начало; потяните её правый край, чтобы изменить длительность. Зелёным за каждой полосой — когда объект виден (минимальная высота и ваш горизонт).",
"Arriba": "Сверху",
"Astrolabio": "Astrolabio",
"Astrolabio anota cada sesión de apilado mientras está conectado al Seestar: el objeto, la hora, los fotogramas y el tiempo de integración. Cuando apiles algo, aparecerá aquí. También puedes traer las sesiones anteriores con «Importar del Seestar».": "Astrolabio записывает каждый сеанс сложения при подключении к Seestar: объект, время, кадры и время накопления. Когда вы что-нибудь сложите, это появится здесь. Прошлые сеансы можно загрузить кнопкой «Импорт из Seestar».",
"Astrolabio es independiente y no está afiliado a ZWO.": "Astrolabio — независимое приложение, не связанное с ZWO.",
"Astrolabio mide el tamaño de las estrellas en cada apilado. Si crecen, suele ser el enfoque (cambio de temperatura) o rocío en la lente.": "Astrolabio измеряет размер звёзд в каждом накоплении. Если они растут, обычно дело в фокусе (смена температуры) или росе на объективе.",
"Astrolabio puede avisarte en el móvil de lo que pasa durante la noche, aunque estés lejos del Mac. **No hace falta número de teléfono ni crear una cuenta**: se usa ntfy, una app gratuita para iPhone y Android.": "Astrolabio может присылать на телефон уведомления о том, что происходит ночью, даже когда вы далеко от Mac. **Номер телефона и учётная запись не нужны**: используется ntfy — бесплатное приложение для iPhone и Android.",
"Autenticación correcta.": "Аутентификация успешна.",
"Autenticado": "Аутентифицирован",
"Autor": "Автор",
"Avanzado": "Дополнительно",
