"Copia del %@ con %@ sesiones, %@ objetos en el plan y %@ proyectos. Sustituirá lo que tienes ahora. Astrolabio se cerrará para cargarla.": "Копия от %@: сеансов — %@, объектов в плане — %@, проектов — %@. Она заменит текущие данные. Astrolabio закроется, чтобы загрузить её.",
"Copia guardada: %@ sesiones, %@ objetos en el plan y %@ proyectos.": "Копия сохранена: сеансов — %@, объектов в плане — %@, проектов — %@.",
"Copia las carpetas elegidas con todos sus archivos, comprueba cada uno y continúa donde lo dejó. No borra nada del telescopio.": "Копирует выбранные папки со всеми файлами, проверяет каждый и продолжает с места остановки. С телескопа ничего не удаляется.",
"Copia terminada: %@ archivos nuevos, %@ ya estaban, %@ con error. Todo comprobado (tamaño y SHA-256) en %@/Álbum.": "Копирование завершено: новых файлов — %@, уже были — %@, с ошибкой — %@. Всё проверено (размер и SHA-256) в %@/Álbum.",
