"Cómo funciona: eliges un «tema», que es como el nombre de un canal privado. Astrolabio publica los avisos en ese tema y la app ntfy del móvil, suscrita a él, te los muestra como notificaciones.": "Как это работает: вы выбираете «тему» — это как название закрытого канала. Astrolabio публикует уведомления в эту тему, а подписанное на неё приложение ntfy показывает их на телефоне.",
