"Dibuja con el ratón la altura de lo que tapa el cielo desde tu sitio: árboles, tejados, montes. Los objetos que queden detrás no se sugieren y la sesión automática los espera o los salta.": "Нарисуйте мышью высоту того, что закрывает небо с вашего места: деревья, крыши, холмы. Объекты за ними не предлагаются, а автоматический сеанс ждёт их или пропускает.",
