"El FITS conserva los datos lineales para procesarlos en Siril o GraXpert.": "FITS сохраняет линейные данные для обработки в Siril или GraXpert.",
"El GoTo a %@ no terminó bien (¿nubes o poca altura?).": "Наведение на %@ не завершилось (облака или слишком низко?).",
"El GoTo a %@ no terminó bien.": "Наведение на %@ не завершилось.",
"El GoTo no terminó bien (¿nubes o poca altura?).": "Наведение не завершилось (облака или слишком низко?).",
"El Pesebre": "Ясли",
"El Seestar debe estar en modo estación (unido a tu wifi). Actívalo una vez desde la app oficial.": "Seestar должен быть в режиме станции (подключён к вашему Wi-Fi). Включите его один раз в официальном приложении.",
"El Seestar tiene un %@ %% y el plan dura unas %@ h; con tu consumo medio (%@ %%/h) terminaría sin batería. Conecta el cargador o acorta el plan.": "У Seestar %@ %%, план длится около %@ ч; при вашем среднем расходе (%@ %%/ч) батарея разрядится. Подключите зарядку или сократите план.",
"El Seestar ve la Luna entera de una vez (su campo mide 44′ × 77′ y la Luna unos 31′), así que no hace falta apuntar a cada cráter: usa el modo Luna y amplía la imagen.": "Seestar видит всю Луну сразу (поле 44′ × 77′, Луна около 31′), так что наводиться на каждый кратер не нужно: включите лунный режим и увеличьте изображение.",
"El archivo PEM no es válido.": "Файл PEM недействителен.",
"El archivo es demasiado grande para ser una copia de Astrolabio.": "Файл слишком большой для копии Astrolabio.",
"El archivo no contiene vídeo.": "Файл не содержит видео.",
"El enfoque automático falló.": "Автофокус не удался.",
"El enfoque falló; se sigue con el enfoque actual.": "Фокусировка не удалась; продолжаем с текущим фокусом.",
"El firmware reciente del Seestar exige que el cliente firme un reto con una clave privada. Indica aquí el archivo .pem que uses con seestar_alp (opción interop_pem).": "Новая прошивка Seestar требует, чтобы клиент подписывал запрос закрытым ключом. Укажите здесь файл .pem, который вы используете с seestar_alp (параметр interop_pem).",
"El modo Luna sigue la Luna y muestra la imagen en «Vista en directo». Para un mosaico o un vídeo, graba con la app y apílalo en «Apilador planetario».": "Режим Луны отслеживает Луну и показывает изображение в «Живом просмотре». Для мозаики или видео снимите в приложении и сложите в «Планетном стекере».",
"El plan de la noche ha terminado.": "План на ночь выполнен.",
"El plan de la sesión automática ha terminado.": "План автоматического сеанса выполнен.",
"El plan está vacío. Añade objetos desde «Planificar la noche» o «Mosaicos».": "План пуст. Добавьте объекты в разделах «План на ночь» или «Мозаики».",
"El plan termina a las %@, %@ min después del amanecer.": "План заканчивается в %@, через %@ мин после рассвета.",
"El plan termina a las %@; sobran %@ min de noche.": "План заканчивается в %@; остаётся %@ мин ночи.",
