"Incluye los ajustes, tus horizontes, el plan, los proyectos y el historial de sesiones. La clave PEM no se copia nunca: tendrás que volver a elegirla.": "Включает настройки, ваши горизонты, план, проекты и историю сеансов. Ключ PEM никогда не копируется: его нужно будет выбрать заново.",
