"La Luna aún no ha salido: aprovecha ahora para los objetos más débiles.": "Луна ещё не взошла: самое время для самых слабых объектов.",
"La Luna está a %.0f°%@.": "Луна в %.0f°%@.",
"La Luna ilumina todo el cielo: buena noche para la Luna, los planetas y las estrellas dobles.": "Луна освещает всё небо: хорошая ночь для Луны, планет и двойных звёзд.",
"La Luna y %@": "Луна и %@",
"La clave PEM la pueden leer otros usuarios de este Mac. Protégela con: chmod 600 \"%@\"": "Ключ PEM могут прочитать другие пользователи этого Mac. Защитите его командой: chmod 600 \"%@\"",
"La copia es de una versión más nueva de Astrolabio. Actualiza la app primero.": "Копия создана более новой версией Astrolabio. Сначала обновите приложение.",
"La duración es fotogramas × exposición configurada.": "Длительность = кадры × заданная выдержка.",
"La imagen es demasiado grande.": "Изображение слишком большое.",
"La lista muestra las zonas con avisos en los últimos días; si la tuya no aparece, vuelve a mirar otro día.": "В списке зоны с предупреждениями за последние дни; если вашей нет, проверьте в другой день.",
"La semana": "Неделя",
"La sesión automática apunta, enfoca, apila y pasa al siguiente sola.": "Автоматический сеанс сам наводится, фокусируется, складывает и переходит к следующему.",
"La sesión se ha puesto en pausa porque se prevén nubes.": "Сеанс приостановлен: ожидаются облака.",
"Las Pléyades": "Плеяды",
"Las coordenadas son J2000; se pasan a la fecha antes de enviarlas.": "Координаты J2000; перед отправкой они пересчитываются на текущую эпоху.",
"Las estrellas han perdido nitidez: se vuelve a enfocar.": "Звёзды потеряли резкость: повторная фокусировка.",
"Las horas son aproximadas (unos minutos). Las conjunciones se dan con la separación mínima vista desde el centro de la Tierra.": "Время приблизительное (несколько минут). Соединения даны по минимальному расстоянию, видимому из центра Земли.",
"Las noches más oscuras del mes: lo mejor para galaxias y nebulosas débiles.": "Самые тёмные ночи месяца: лучшее время для слабых галактик и туманностей.",
"Latitud (°, norte positivo)": "Широта (°, север положительный)",
"Le quedan %.1f h por encima de %.0f°: %.0f min de apilado dan buen resultado.": "Над %2$.0f° осталось %1$.1f ч: %3$.0f мин сложения дадут хороший результат.",
