"Listas": "Списки",
"Llegó a %@.": "Наведено на %@.",
"Lo mejor ahora": "Лучшее сейчас",
"Lo que pasa en el cielo en las próximas seis semanas, calculado para tu lugar.": "Что произойдёт в небе за следующие шесть недель, с расчётом для вашего места.",
"Longitud (°, este positivo)": "Долгота (°, восток положительный)",
"Los %d accidentes de la lista": "%d объектов в списке",
"Los anillos se distinguen incluso con el Seestar.": "Кольца видны даже в Seestar.",
"Los avisos también salen siempre como notificación en el Mac. Solo contienen el nombre del objeto y lo ocurrido.": "Уведомления также всегда появляются на Mac. В них только название объекта и что произошло.",
"Los mejores objetos para el Seestar": "Лучшие объекты для Seestar",
"Los nombres solo se dibujan sin recorte.": "Названия рисуются только без кадрирования.",
"Los próximos 30 días": "Ближайшие 30 дней",
"Los relieves lucen más junto al terminador, la línea entre el día y la noche lunar: allí el Sol está bajo y las sombras son largas.": "Рельеф лучше всего виден у терминатора — границы лунного дня и ночи: там Солнце низко и тени длинные.",
